namespace StarlightSyndicateDemo;
public sealed record InformationRow(string Label,string Value="",string Link="",bool Heading=false);
public sealed class InformationEntry
{
 public string Key="",Id="",Name="",Kind="",Group="",Description="",MarketId="",System="";public bool LastSeen;
 public Dictionary<string,List<InformationRow>> Tabs=[];
 public Dictionary<string,string> Stats=[];
 public List<string> Related=[];
 public List<InformationRow> Tab(string name){if(!Tabs.TryGetValue(name,out var rows))Tabs[name]=rows=[];return rows;}
 public void Add(string tab,string label,string value="",string link="",bool heading=false)=>Tab(tab).Add(new(label,value,link,heading));
}
public static class InformationCatalog
{
 public static readonly Dictionary<string,InformationEntry> ByKey;
 public static readonly InformationEntry[] All;
 static InformationCatalog(){ByKey=Build();All=ByKey.Values.Concat(UnifiedCatalog40.Summaries()).Concat(Retheme41.Summaries()).OrderBy(e=>e.Group).ThenBy(e=>e.Name).ToArray();}
 public static string ItemKey(string id)=>"item/"+id;
 public static string Label(string name)=>Regex.Replace(name,"(?<=[a-z0-9])([A-Z])"," $1").Replace("Cpu","CPU");
 static readonly HashSet<string> FittingFields=["Cpu","Power","Slot","Size","MaxGroup","Magazine","ShipCap","CapitalCap","Calibration","Capacity","Bandwidth","Tubes"];
 static readonly HashSet<string> SkipFields=["Id","Name","Description","ReferenceName","ReferenceTypeId","DisplayFamily","Mechanic","SizeLabel","Group"];
 public static InformationEntry TypeEntry(ItemDefinition item,object? definition){var e=new InformationEntry{Key=ItemKey(item.Id),Id=item.Id,Name=item.Name,Kind=item.Slot=="drone"?"Drone":item.Slot=="charge"?"Charge":item.Slot.Length>0?"Module":"Material",Group=MarketGroups.PathFor(item),Description=item.Description,MarketId=item.Id};e.Add("Description",item.Description);e.Add("Attributes","Volume",$"{item.Volume:0.###} m3");e.Stats["Volume"]=$"{item.Volume:0.###} m3";e.Add("Attributes","Base price",$"{item.Price:N2} CR");e.Add("Fitting","Slot",item.Slot.Length==0?"Cargo item":item.Slot);e.Add("Requirements","Usage","Read role, size and compatibility restrictions below; fitting budgets and online state are enforced by the game.");
 if(definition!=null)foreach(var p in definition.GetType().GetProperties(BindingFlags.Public|BindingFlags.Instance)){if(SkipFields.Contains(p.Name)||p.GetIndexParameters().Length>0)continue;object? v=p.GetValue(definition);if(v==null)continue;if(v is System.Collections.IDictionary dictionary){foreach(System.Collections.DictionaryEntry b in dictionary){string key=b.Key.ToString()!;string value=b.Value is float f?(key.Contains("Resonance")?DemoGame.InfoValue(key,f):key.EndsWith("Add")?f.ToString("+0.###;-0.###;0"):f.ToString("+0.0%;-0.0%;0%")):b.Value?.ToString()??"";e.Add("Attributes",Label(key),value);e.Stats[Label(key)]=value;}continue;}if(v is not(string or bool or Enum or float or double or int or decimal))continue;string text=definition is MobilityDefinition&&p.Name is "Speed" or "Signature"?Convert.ToDouble(v).ToString("+0.0%;-0.0%;0%"):(definition is DroneDefinition&&p.Name=="Speed"?Convert.ToDouble(v).ToString("0.0")+" m/s":Format(p.Name,v));if(text.Length==0)continue;string tab=p.Name=="Role"?"Requirements":FittingFields.Contains(p.Name)?"Fitting":"Attributes";e.Add(tab,Label(p.Name),text);e.Stats[Label(p.Name)]=text;}
 if(definition!=null){var json=JsonSerializer.SerializeToElement(definition,definition.GetType(),WeaponCatalog.JsonOptions);foreach(var field in json.EnumerateObject().Where(f=>f.Value.ValueKind is JsonValueKind.Array or JsonValueKind.Object))NestedDefinition(e,field.Name,field.Value);}
 e.Tab("Variations");e.Add("Industry","Acquisition","Use regional market listings and inventory. No fabrication recipe is defined for this type.");return e;}
 public static string Format(string field,object value){if(value is bool b)return b?"Yes":"No";if(value is string s)return s; if(value is Enum)return value.ToString()!;double n=Convert.ToDouble(value,System.Globalization.CultureInfo.InvariantCulture);string unit=field switch{"Cpu"=>" tf","Power"=>" MW","Volume"=>" m3","Price"=>" CR","Capacitor"=>" GJ","Cycle" or "Duration" or "Reload" or "Reactivation" or "Warmup" or "FlightTime" or "PostScram"=>" s","Velocity" or "ExplosionVelocity"=>" m/s","Optimal" or "Falloff" or "Range" or "JumpRange" or "Radius" or "ExplosionRadius" or "SignatureResolution"=>" m","MassAddition" or "Mass"=>" kg","Tracking"=>" rad/s",_=>""};return n.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)+unit;}
 static void NestedDefinition(InformationEntry e,string path,JsonElement element){if(element.ValueKind==JsonValueKind.Object){foreach(var p in element.EnumerateObject())NestedDefinition(e,path+" / "+Label(p.Name),p.Value);}else if(element.ValueKind==JsonValueKind.Array){int i=0;foreach(var v in element.EnumerateArray())NestedDefinition(e,path+" / "+(++i),v);}else{string text=element.ToString();e.Add("Details",path,text);if(element.ValueKind==JsonValueKind.Number)e.Stats[path]=text;}}
 static Dictionary<string,InformationEntry> Build(){var result=new Dictionary<string,InformationEntry>();void Add(InformationEntry e)=>result[e.Key]=e;
 var defs=new Dictionary<string,object>();void Definitions<T>(IEnumerable<T> values){foreach(var d in values){if(d==null)continue;var id=d.GetType().GetProperty("Id")?.GetValue(d)?.ToString();if(id!=null)defs[id]=d;}}
 Definitions(WeaponCatalog.ById.Values);Definitions(ChargeCatalog.All);Definitions(EwarCatalog.All);Definitions(EwarPayloads.All);Definitions(DefenseCatalog.All);Definitions(DefensePayloads.All);Definitions(SupportCatalog.All);Definitions(SupportPayloads.New);Definitions(EnhancementCatalog.All);Definitions(EnhancementCatalog.NewScripts);Definitions(MobilityCatalog.All);Definitions(UtilityCatalog.All);Definitions(UtilityPayloads.All);Definitions(SpecialCatalog.All);Definitions(RigCatalog.All);Definitions(DroneCatalog.All);Definitions(ShipBatch28.Subsystems);
 foreach(var item in ItemCatalog.All.DistinctBy(i=>i.Id).Where(i=>i.Slot!="ship"))Add(TypeEntry(item,defs.GetValueOrDefault(item.Id)));
 foreach(var h in FleetCatalog.All){var e=new InformationEntry{Key=ItemKey(h.Id),Id=h.Id,Name=h.Name,Kind="Ship",Group="Ships / "+h.Class+" / "+h.Faction,Description=h.Description+"\n\n"+h.Quote,MarketId=h.Playable&&ItemCatalog.All.Any(i=>i.Id==h.Id)?h.Id:""};e.Tab("Fitting");e.Add("Description",e.Description);e.Add("Description","Faction",h.Faction,"faction/"+h.Faction);e.Add("Description","Integration",h.Playable?"Playable":"Reference hull — mechanics integration pending");
 foreach(var group in h.Attributes.OrderBy(k=>k.Key).GroupBy(k=>ShipAttributeCatalog.ByKey.GetValueOrDefault(k.Key)?.Group??"Other")){string tab=group.Key=="Fitting"?"Fitting":"Attributes";e.Add(tab,group.Key.ToUpper(),heading:true);foreach(var p in group){string label=ShipAttributeCatalog.ByKey.GetValueOrDefault(p.Key)?.Label??Label(p.Key);string value=DemoGame.InfoValue(p.Key,p.Value);e.Add(tab,label,value);e.Stats[label]=value;}}
 foreach(var p in h.RawFields.Where(p=>p.Key.Contains("Skill",StringComparison.OrdinalIgnoreCase)))e.Add("Requirements",Label(p.Key),p.Value);e.Add("Requirements","Training status","Live pilot qualifications and prerequisite training are shown here.");
 if(ShipBatch21.ById.TryGetValue(h.Id,out var profile))foreach(var t in profile.Traits)e.Add("Traits",(t.Skill==0?"Role":"Per level")+" / "+t.Bonus+(t.Unit==105?"%":""),t.Text);
 e.Tab("Model");e.Tab("Variations");e.Add("Industry","Acquisition",h.Playable?"Regional market / fleet registry. No fabrication blueprint is defined.":"Reference hull only; not purchasable or flyable.");foreach(var p in h.RawFields.OrderBy(p=>p.Key))e.Add("Source",p.Key,p.Value);Add(e);}
 foreach(var s in DemoWorld.Systems){var e=new InformationEntry{Key="system/"+s.Id,Id=s.Id,Name=s.Name,Kind="Solar system",Group="Universe / Solar systems / "+s.Region,Description=s.Description,System=s.Id};e.Add("Description",s.Description);e.Add("Attributes","Security status",s.Security.ToString("0.0"));e.Add("Attributes","Region",s.Region,"region/"+s.Region);e.Add("Attributes","Sovereignty",s.Faction,"faction/"+s.Faction);e.Add("Attributes","Local grid width","8,000 km");foreach(var c in SolarCatalog.Systems[s.Id])e.Add(c.Kind==CelestialKind.Station?"Stations":c.Kind==CelestialKind.Beacon?"Structures":"Orbital Bodies",c.Name,c.Type,"celestial/"+c.Id);e.Tab("Structures");foreach(var link in s.Links){var neighbor=DemoWorld.Systems.First(n=>n.Id==link);e.Add("Neighbors",neighbor.Name,neighbor.Security.ToString("0.0"),"system/"+link);}e.Tab("Route");Add(e);}
 foreach(var region in DemoWorld.Systems.GroupBy(s=>s.Region)){var e=new InformationEntry{Key="region/"+region.Key,Id=region.Key,Name=region.Key,Kind="Region",Group="Universe / Regions",Description="A region of the Starlight cluster containing "+region.Count()+" charted solar systems."};e.Add("Description",e.Description);e.Add("Attributes","Solar systems",region.Count().ToString());e.Add("Attributes","Security range",$"{region.Min(s=>s.Security):0.0} – {region.Max(s=>s.Security):0.0}");foreach(var s in region)e.Add("Solar Systems",s.Name,s.Security.ToString("0.0"),"system/"+s.Id);Add(e);}
 foreach(var c in SolarCatalog.ById.Values){var system=DemoWorld.Systems.First(s=>s.Id==c.System);var e=new InformationEntry{Key="celestial/"+c.Id,Id=c.Id,Name=c.Name,Kind=c.Kind.ToString(),Group="Universe / "+CelestialGroup(c.Kind)+" / "+system.Region,Description=c.Type+" in "+system.Name+".",System=c.System};e.Add("Description",e.Description);e.Add("Attributes","Type",c.Type);e.Add("Attributes","Solar system",system.Name,"system/"+c.System);e.Add("Attributes","Region",system.Region,"region/"+system.Region);e.Add("Attributes","Radius",SolarCatalog.Distance(c.Radius));e.Add("Attributes","Distance from star",SolarCatalog.Distance(c.Position.Length));if(c.Parent.Length>0)e.Add("Attributes","Parent",SolarCatalog.ById.GetValueOrDefault(c.Parent)?.Name??c.Parent,"celestial/"+c.Parent);if(c.Destination.Length>0)e.Add("Attributes","Destination",DemoWorld.Systems.First(s=>s.Id==c.Destination).Name,"system/"+c.Destination);foreach(var child in SolarCatalog.Systems[c.System].Where(n=>n.Parent==c.Id))e.Add("Orbital Bodies",child.Name,child.Type,"celestial/"+child.Id);if(c.Kind==CelestialKind.Station)foreach(var service in new[]{"Docking","Hangar and cargo","Fitting and repairs","Regional market","Fleet registry"})e.Add("Services",service,"Available");Add(e);}
 foreach(var f in JsonSerializer.Deserialize<JsonElement[]>(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"Assets","Factions.json")))!){string name=f.GetProperty("Name").GetString()!;var e=new InformationEntry{Key="faction/"+name,Id=name,Name=name,Kind="Faction",Group="Organizations / Factions",Description=f.GetProperty("Lore").GetString()!};e.Add("Description",e.Description);e.Add("Attributes","Role",f.GetProperty("Role").GetString()!);foreach(var h in FleetCatalog.All.Where(h=>h.Faction==name))e.Add("Ships",h.Name,h.Class,ItemKey(h.Id));Add(e);}
 foreach(var group in DemoWorld.Systems.GroupBy(s=>s.Faction)){if(!result.TryGetValue("faction/"+group.Key,out var e)){e=new(){Key="faction/"+group.Key,Id=group.Key,Name=group.Key,Kind="Organization",Group="Organizations / Cluster authorities",Description=group.Key=="Unclaimed"?"No recognized sovereignty authority claims these systems.":group.Key+" administers local facilities and trade in the charted cluster."};e.Add("Description",e.Description);Add(e);}foreach(var s in group)e.Add("Solar Systems",s.Name,s.Security.ToString("0.0"),"system/"+s.Id);}
 // Variations and charge compatibility are cached relationships, never rebuilt during drawing.
 foreach(var e in result.Values.Where(e=>e.Kind is "Ship" or "Module" or "Charge" or "Drone" or "Material")){IEnumerable<InformationEntry> variants;if(e.Kind=="Ship"){var h=FleetCatalog.ById[e.Id];string root=h.BaseHullId.Length>0?h.BaseHullId:h.Id;variants=result.Values.Where(v=>v.Kind=="Ship"&&(v.Id==root||FleetCatalog.ById[v.Id].BaseHullId==root));}else variants=result.Values.Where(v=>v.Kind==e.Kind&&v.Group==e.Group);foreach(var v in variants.OrderBy(v=>v.Name)){e.Related.Add(v.Key);e.Add("Variations",v.Name,v.Kind,v.Key);}if(WeaponCatalog.ById.TryGetValue(e.Id,out var w))foreach(var c in ChargeCatalog.For(w))e.Add("Used With",c.Name,c.Payload,ItemKey(c.Id));if(UtilityCatalog.ById.TryGetValue(e.Id,out var u))foreach(var c in UtilityPayloads.All.Where(c=>UtilityPayloads.Fits(u,c)))e.Add("Used With",c.Name,c.Kind,ItemKey(c.Id));if(e.Tab("Variations").Count==0)e.Add("Variations","No recorded variations.");}
 foreach(var item in ItemCatalog.All){if(!result.TryGetValue(ItemKey(item.Id),out var e))continue;var recipe=IndustryCatalog37.Recipes[item.Id];e.Tabs["Industry"]=[];e.Add("Industry","Blueprint",recipe.Provenance);e.Add("Industry","Production batch",recipe.Definition.Output+" units per run");e.Add("Industry","Base production time",recipe.Definition.Seconds+" seconds");e.Add("Industry","Maximum runs per copy",recipe.Definition.MaxRuns.ToString());e.Add("Industry","Research limits","ME 10% / TE 20%; originals only");e.Add("Industry","Build skills",string.Join(", ",IndustryCatalog37.BuildSkills(recipe,false).Select(s=>(SkillCatalog.ById.GetValueOrDefault(s.Skill)?.Name??s.Skill.ToString())+" "+s.Level)));e.Add("Industry","MINERAL FABRICATION / STARLIGHT ADAPTATION",heading:true);foreach(var m in recipe.Minerals)e.Add("Industry",ItemCatalog.Get(m.Key).Name,m.Value.ToString("N0"),ItemKey(m.Key));e.Add("Industry","CCP COMPONENT RECIPE",heading:true);foreach(var m in recipe.Native)e.Add("Industry",ItemCatalog.Get(m.Key).Name,m.Value.ToString("N0"),ItemKey(m.Key));}
 foreach(var entry in result.Values){if(entry.Key.StartsWith("item/"))UnifiedCatalog40.AttachSource(entry);Retheme41.Sanitize(entry);}
 return result;}
 static string CelestialGroup(CelestialKind k)=>k switch{CelestialKind.Planet=>"Planets",CelestialKind.Moon=>"Moons",CelestialKind.Sun=>"Stars",CelestialKind.Station=>"Stations",CelestialKind.Stargate=>"Stargates",CelestialKind.Wormhole=>"Wormholes",CelestialKind.AsteroidBelt or CelestialKind.IceField or CelestialKind.GasCloud=>"Resource sites",_=>"Sites and beacons"};
